<?php
require_once __DIR__.'/_header.php';$page_title='Documentary Archive';$id=(int)($_GET['id']??0);$types=['DOCUMENTARY','INTERVIEW','RECORDING','NEWS_REPORT','OTHER'];
if(isset($_GET['delete'])&&user()['role']==='ADMIN'){db()->prepare('DELETE FROM documentaries WHERE id=?')->execute([(int)$_GET['delete']]);flash('success','Documentary deleted.');redirect('/admin/documentaries.php');}
$row=['title'=>'','media_type'=>'DOCUMENTARY','video_url'=>'','description'=>'','event_date'=>'','location'=>'','story_id'=>'','source_name'=>'','thumbnail_url'=>'','status'=>'DRAFT'];if($id){$s=db()->prepare('SELECT * FROM documentaries WHERE id=?');$s->execute([$id]);$found=$s->fetch();if(!$found)exit('Documentary not found.');$row=$found;}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$data=['title'=>trim($_POST['title']??''),'media_type'=>in_array($_POST['media_type']??'', $types,true)?$_POST['media_type']:'DOCUMENTARY','video_url'=>trim($_POST['video_url']??''),'description'=>trim($_POST['description']??''),'event_date'=>($_POST['event_date']??'')?:null,'location'=>trim($_POST['location']??''),'story_id'=>($_POST['story_id']??'')?:null,'source_name'=>trim($_POST['source_name']??''),'thumbnail_url'=>trim($_POST['thumbnail_url']??''),'status'=>($_POST['status']??'DRAFT')==='PUBLISHED'?'PUBLISHED':'DRAFT'];$parts=parse_url($data['video_url']);$host=strtolower($parts['host']??'');if($data['title']===''||$data['video_url']===''||!filter_var($data['video_url'],FILTER_VALIDATE_URL)||!in_array($host,['youtube.com','www.youtube.com','youtu.be','vimeo.com','www.vimeo.com'],true)){flash('error','Title and a valid YouTube or Vimeo URL are required.');$row=array_merge($row,$data);}else{try{if($id){$sql='UPDATE documentaries SET title=?,media_type=?,video_url=?,description=?,event_date=?,location=?,story_id=?,source_name=?,thumbnail_url=?,status=?,updated_by=? WHERE id=?';db()->prepare($sql)->execute([...array_values($data),user()['id'],$id]);}else{$sql='INSERT INTO documentaries(title,media_type,video_url,description,event_date,location,story_id,source_name,thumbnail_url,status,created_by,updated_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)';db()->prepare($sql)->execute([...array_values($data),user()['id'],user()['id']]);}flash('success',$id?'Documentary updated.':'Documentary saved.');redirect('/admin/documentaries.php');}catch(Throwable $e){flash('error','Could not save documentary.');$row=array_merge($row,$data);}}}
$stories=db()->query("SELECT id,title FROM stories WHERE status='PUBLISHED' ORDER BY title")->fetchAll();$docs=db()->query('SELECT d.*,s.title story_title FROM documentaries d LEFT JOIN stories s ON s.id=d.story_id ORDER BY d.created_at DESC')->fetchAll();
?><div class="content"><form class="form" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="formgrid"><div class="field full"><label>Title *</label><input name="title" value="<?=e($row['title'])?>" required></div><div class="field"><label>Media type</label><select name="media_type"><?php foreach($types as $type):?><option value="<?=$type?>" <?=$row['media_type']===$type?'selected':''?>><?=e(str_replace('_',' ',$type))?></option><?php endforeach;?></select></div><div class="field"><label>Video URL *</label><input type="url" name="video_url" value="<?=e($row['video_url'])?>" placeholder="https://youtube.com/watch?v=..." required></div><div class="field"><label>Event date</label><input type="date" name="event_date" value="<?=e($row['event_date'])?>"></div><div class="field"><label>Location</label><input name="location" value="<?=e($row['location'])?>"></div><div class="field"><label>Source / producer</label><input name="source_name" value="<?=e($row['source_name'])?>"></div><div class="field"><label>Related archive story</label><select name="story_id"><option value="">None</option><?php foreach($stories as $story):?><option value="<?=$story['id']?>" <?=$row['story_id']==$story['id']?'selected':''?>><?=e($story['title'])?></option><?php endforeach;?></select></div><div class="field full"><label>Thumbnail URL (optional)</label><input type="url" name="thumbnail_url" value="<?=e($row['thumbnail_url'])?>"></div><div class="field full"><label>Description</label><textarea name="description"><?=e($row['description'])?></textarea></div><div class="field"><label>Status</label><select name="status"><option value="DRAFT" <?=$row['status']==='DRAFT'?'selected':''?>>Draft</option><option value="PUBLISHED" <?=$row['status']==='PUBLISHED'?'selected':''?>>Published</option></select></div></div><div class="actions"><button>Save documentary</button><?php if($id):?><a class="btn secondary" href="?delete=<?=$id?>" data-confirm="Delete this documentary?">Delete</a><?php endif;?></div></form><div class="tablewrap" style="margin-top:25px"><table><thead><tr><th>Title</th><th>Type</th><th>Related story</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($docs as $doc):?><tr><td><?=e($doc['title'])?></td><td><?=e($doc['media_type'])?></td><td><?=e($doc['story_title']??'—')?></td><td><?=e($doc['status'])?></td><td><a class="btn secondary" href="?id=<?=$doc['id']?>">Edit</a></td></tr><?php endforeach;?><?php if(!$docs):?><tr><td colspan="5">No documentaries added yet.</td></tr><?php endif;?></tbody></table></div></div><?php require_once __DIR__.'/_footer.php';
